-- 0146: two more iʿlāl rules bound too widely by ilal_locus_bind/v1 (after the Form VIII four, 0144).
--   IR:hadhf:12 (the و of an و-first verb drops in the present: وَعَدَ يَعِدُ) holds for Form I only — derived forms keep
--   it (أَوْحَى يُوحِي، تَوَكَّلَ) — and not for وَجِلَ (samiʿa: لا تَوْجَلْ 15:53), the passive يُوزَعُ, or يُوصِي (Form IV,
--   mis-tagged I). Kept 29, rejected 55.
--   IR:qalb:06 (a final weak letter becomes hamza after an added alif: سَمَاء، دُعَاء) holds only for nouns ending in ـاء;
--   it was bound to every noun of a defective root (هُدًى، فِئَة، سِنِين …). Kept 30, rejected 252.
UPDATE ar_ling_root_lemma_ilal_apply SET status = 'rejected', note_en = 'Rejected (0146): the و stays in this verb (not Form I, or a verb that keeps it).' WHERE status = 'live' AND id IN ('ILA:15c8e4b7b017:hadhf:12', 'ILA:e0bf70ad8ac8:hadhf:12', 'ILA:ec6bb9b9ebd9:hadhf:12', 'ILA:bc905ddae1a7:hadhf:12', 'ILA:49564b17a76e:hadhf:12', 'ILA:6718acb49ad9:hadhf:12', 'ILA:211cd420f7de:hadhf:12', 'ILA:6c8cfa2b9901:hadhf:12', 'ILA:8d7597298770:hadhf:12', 'ILA:d969610a8ffe:hadhf:12', 'ILA:192c72146325:hadhf:12', 'ILA:68d3f2515de2:hadhf:12', 'ILA:b66afc969d35:hadhf:12', 'ILA:98a6950aa906:hadhf:12', 'ILA:a7020084eb96:hadhf:12', 'ILA:557dde5cf7b7:hadhf:12', 'ILA:3d159843cb83:hadhf:12', 'ILA:d18351caf486:hadhf:12', 'ILA:23bd02d67a63:hadhf:12', 'ILA:2432cbdd99bd:hadhf:12', 'ILA:7a5c51179363:hadhf:12', 'ILA:fbe7eaabd5af:hadhf:12', 'ILA:2a5831f70144:hadhf:12', 'ILA:a4a7c6ebba90:hadhf:12', 'ILA:cbd8c6743326:hadhf:12', 'ILA:2376b6532a41:hadhf:12', 'ILA:b5d7685ac1a0:hadhf:12', 'ILA:03d9b118ca63:hadhf:12', 'ILA:c1bb998fa20a:hadhf:12', 'ILA:61ae1a9b9717:hadhf:12', 'ILA:f11dc8869f3b:hadhf:12', 'ILA:30449af311c8:hadhf:12', 'ILA:71202d420e96:hadhf:12', 'ILA:1016f2ef75ad:hadhf:12', 'ILA:924587975644:hadhf:12', 'ILA:cdf1fac1804a:hadhf:12', 'ILA:67eafdc7ab30:hadhf:12', 'ILA:e342c7e83c18:hadhf:12', 'ILA:a34f6d9d3095:hadhf:12', 'ILA:67b8fe45dd0a:hadhf:12', 'ILA:5b8d01e78761:hadhf:12', 'ILA:271e102006ae:hadhf:12', 'ILA:020c38f22d41:hadhf:12', 'ILA:adf7bfd65ebb:hadhf:12', 'ILA:91d6bf3e3219:hadhf:12', 'ILA:6cb71fdd2254:hadhf:12', 'ILA:da3baead6241:hadhf:12', 'ILA:605363121318:hadhf:12', 'ILA:ALL:NS:87411:hadhf:12', 'ILA:ALL:NS:3E015:hadhf:12', 'ILA:ALL:NS:264E3:hadhf:12', 'ILA:ALL:NS:B6746:hadhf:12', 'ILA:ALL:NS:A1EB1:hadhf:12', 'ILA:ALL:NS:DD7B8:hadhf:12', 'ILA:ALL:NS:50B9B:hadhf:12');
